import {releaseSetting,releaseMillis} from './release-policy.js';
export function availabilitySpec(mode,startLocal,endLocal){if(!['manual','instant','scheduled'].includes(mode))throw Error('Escolha a forma de liberação.');const start=mode==='scheduled'?releaseSetting('scheduled',startLocal).millis:0,end=endLocal?releaseSetting('scheduled',endLocal).millis:Date.parse('2100-01-01T00:00:00Z');if(end<=start)throw Error('O encerramento deve ocorrer depois da liberação.');return {releaseMode:mode,open:mode!=='manual',startMillis:start,endMillis:end};}
export function availabilityStatus(exam,now=Date.now()){if(!exam.open)return 'Respostas encerradas / aguardando liberação';if((releaseMillis(exam.endAt)??Infinity)<=now)return 'Prazo encerrado';if((releaseMillis(exam.startAt)??0)>now)return 'Liberação agendada';return 'Recebendo respostas';}
